import sys

def main():
    a, b = sys.stdin.read().split()
    n = len(a)
    d = [(int(y) - int(x)) % 10 for x, y in zip(a, b)]
    # cost[s]: fewest single moves (each shifts by at most 3 either way) to shift one window by s modulo 10
    cost = [0, 1, 1, 1, 2, 2, 2, 1, 1, 1]
    INF = 10 ** 9
    cur = {(0, 0): 0}
    for k in range(n):
        nxt = {}
        r2 = 10 if k + 2 <= n else 1
        r3 = 10 if k + 3 <= n else 1
        for (u, v), c in cur.items():
            for s2 in range(r2):
                for s3 in range(r3):
                    s1 = (d[k] - u - s2 - s3) % 10
                    nc = c + cost[s1] + cost[s2] + cost[s3]
                    key = ((v + s2 + s3) % 10, s3)
                    if nc < nxt.get(key, INF):
                        nxt[key] = nc
        cur = nxt
    print(min(cur.values()))

main()

